  'reflection.saved': { es: '¡Guardado! 🌸', en: 'Saved! 🌸', pt: 'Guardado! 🌸', it: 'Salvato! 🌸', fr: 'Enregistré ! 🌸', de: 'Gespeichert! 🌸' },
