  'periodicgoal.spendLimit': { es: '🚦 Límite de gasto', en: '🚦 Spending limit', pt: '🚦 Limite de despesa', it: '🚦 Limite di spesa', fr: '🚦 Limite de dépense', de: '🚦 Ausgabenlimit' },
